import json,sys,uuid
for line in sys.stdin:
    try: m=json.loads(line)
    except ValueError: continue
    rid,meth=m.get('id'),m.get('method')
    if rid is None: continue
    if meth=='initialize': r={'protocolVersion':1,'agentInfo':{'name':'claude','title':'Claude','version':'1.0.0'},'agentCapabilities':{'loadSession':False,'promptCapabilities':{}}}
    elif meth=='session/new': r={'sessionId':str(uuid.uuid4())}
    elif meth=='session/prompt':
        sid=m['params'].get('sessionId')
        sys.stdout.write(json.dumps({'jsonrpc':'2.0','method':'session/update','params':{'sessionId':sid,'update':{'sessionUpdate':'agent_message_chunk','content':{'type':'text','text':'Here, in the chat pane.'}}}})+'\n')
        r={'stopReason':'end_turn'}
    else: r={}
    sys.stdout.write(json.dumps({'jsonrpc':'2.0','id':rid,'result':r})+'\n'); sys.stdout.flush()
